function bytes(b64) {
  const bin = atob(b64);
  const a = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) a[i] = bin.charCodeAt(i);
  return a;
}

let _og = null, _icon = null;

export function ogImage() {
  if (!_og) _og = bytes(OG_B64);
  return new Response(_og, {
    headers: { "content-type": "image/jpeg", "cache-control": "public, max-age=604800, immutable" },
  });
}

export function appIcon() {
  if (!_icon) _icon = bytes(ICON_B64);
  return new Response(_icon, {
    headers: { "content-type": "image/png", "cache-control": "public, max-age=604800, immutable" },
  });
}
